import numpy as np
from scipy.ndimage import label

def get_max_component_size(grid, k):
    max_size = 0
    for i in range(k):
        # S_i is cells not colored i
        mask = (grid != i)
        labeled_array, num_features = label(mask)
        if num_features > 0:
            component_sizes = np.bincount(labeled_array.ravel())
            max_size = max(max_size, component_sizes[1:].max())
        else:
            max_size = max(max_size, 0)
    return max_size

def test_pattern(width, height, k, pattern_func):
    grid = np.zeros((width, height), dtype=int)
    for x in range(width):
        for y in range(height):
            grid[x, y] = pattern_func(x, y, k)
    return get_max_component_size(grid, k)

