import itertools
import numpy as np

def get_all_polyominoes_of_size_3(h, w):
    polys = []
    for x in range(h):
        for y in range(w):
            # Horizontal line
            if x + 2 < h: polys.append([(x, y), (x+1, y), (x+2, y)])
            # Vertical line
            if y + 2 < w: polys.append([(x, y), (x, y+1), (x, y+2)])
            # L-shapes
            # (x,y) as corner
            if x+1 < h and y+1 < w:
                polys.append([(x,y), (x+1,y), (x,y+1)])
                polys.append([(x,y), (x-1,y), (x,y+1)]) if x-1 >= 0 else None
                polys.append([(x,y), (x+1,y), (x,y-1)]) if y-1 >= 0 else None
                polys.append([(x,y), (x-1,y), (x,y-1)]) if x-1 >= 0 and y-1 >= 0 else None
    # Remove duplicates
    unique_polys = []
    for p in polys:
        if p is None: continue
        s = sorted(p)
        if s not in unique_polys:
            unique_polys.append(s)
    return unique_polys

def check_coloring(grid, k):
    h, w = grid.shape
    polys = get_all_polyominoes_of_size_3(h, w)
    for p in polys:
        colors = {grid[x,y] for x,y in p}
        if len(colors) < k:
            return False
    return True

def solve():
    for coloring in itertools.product(range(3), repeat=9):
        grid = np.array(coloring).reshape(3, 3)
        if check_coloring(grid, 3):
            print("Found one!")
            print(grid)
            return True
    print("No coloring found")
    return False

